<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/auth.php';$user=require_role('admin');$pdo=db();
if(is_post()){verify_csrf();$target=(int)($_POST['user_id']??0);$action=$_POST['action']??'';if($target===(int)$user['id']){flash('error','You cannot change your own administrator access.');redirect('admin/users.php');}if($action==='toggle'){$stmt=$pdo->prepare('UPDATE users SET is_active=1-is_active WHERE id=? AND role<>"admin"');$stmt->execute([$target]);flash($stmt->rowCount()?'success':'error',$stmt->rowCount()?'Account status updated.':'Only donor or charity accounts can be changed.');}elseif($action==='verify'){$stmt=$pdo->prepare('UPDATE charities c JOIN users u ON u.id=c.user_id SET c.verified=1-c.verified WHERE c.user_id=?');$stmt->execute([$target]);flash($stmt->rowCount()?'success':'error',$stmt->rowCount()?'Charity verification updated.':'Charity account not found.');}else{http_response_code(400);exit('Invalid action.');}redirect('admin/users.php');}
$role=$_GET['role']??'';$sql='SELECT u.*,c.organization_name,c.verified FROM users u LEFT JOIN charities c ON c.user_id=u.id';$params=[];if(in_array($role,['donor','charity','admin'],true)){$sql.=' WHERE u.role=?';$params[]=$role;}$sql.=' ORDER BY u.created_at DESC';$stmt=$pdo->prepare($sql);$stmt->execute($params);$users=$stmt->fetchAll();$pageTitle='Manage people';require __DIR__ . '/../includes/header.php'; ?>
<section class="dashboard"><div class="shell"><div class="welcome-row"><div><span class="eyebrow">Community safety</span><h1>People & organisations</h1><p>Review account access and charity verification status.</p></div><a class="button button-outline" href="<?=e(url('admin/dashboard.php'))?>">Admin overview</a></div><div class="filter-card" style="margin:0 0 20px"><div class="request-meta"><a class="chip <?=!$role?'chip-sun':''?>" href="<?=e(url('admin/users.php'))?>">Everyone</a><?php foreach(['donor','charity','admin'] as $r):?><a class="chip <?=$role===$r?'chip-sun':''?>" href="<?=e(url('admin/users.php?role='.$r))?>"><?=e(ucfirst($r).'s')?></a><?php endforeach;?></div></div><div class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Person</th><th>Role</th><th>Organisation</th><th>Joined</th><th>Account</th><th>Actions</th></tr></thead><tbody><?php foreach($users as $account):?><tr><td><strong><?=e($account['name'])?></strong><br><span class="muted"><?=e($account['email'])?></span></td><td><span class="chip"><?=e($account['role'])?></span></td><td><?=e($account['organization_name']??'—')?><?php if($account['role']==='charity'):?><br><small class="<?= $account['verified']?'text-link':'muted'?>"><?= $account['verified']?'Verified':'Unverified'?></small><?php endif;?></td><td><?=format_date($account['created_at'])?></td><td><span class="status <?= $account['is_active']?'status-success':'status-danger'?>"><?= $account['is_active']?'active':'inactive'?></span></td><td class="row-actions"><?php if($account['role']!=='admin'):?><form method="post" data-loading data-confirm="<?= $account['is_active']?'Deactivate this account?':'Restore this account?' ?>"><?=csrf_field()?><input type="hidden" name="user_id" value="<?=$account['id']?>"><input type="hidden" name="action" value="toggle"><button class="button button-small <?=$account['is_active']?'button-danger':'button-sun'?>"><?=$account['is_active']?'Deactivate':'Restore'?></button></form><?php endif;?><?php if($account['role']==='charity'):?><form method="post" data-loading><?=csrf_field()?><input type="hidden" name="user_id" value="<?=$account['id']?>"><input type="hidden" name="action" value="verify"><button class="button button-small button-outline"><?=$account['verified']?'Unverify':'Verify'?></button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></div></section>
<?php require __DIR__ . '/../includes/footer.php'; ?>
